import sqlite3, json
from collections import defaultdict

STEPS = ['install', 'tutorial_complete', 'first_match', 'purchase']
c = sqlite3.connect('analytics.db')

print(sorted({r[0] for r in c.execute('select distinct name from events')}))
print(sorted({r[0] for r in c.execute('select distinct platform from users')}))
unknown = c.execute("select count(*) from events e left join users u on e.user_id=u.user_id where u.user_id is null").fetchone()[0]
print('events w/ unknown player:', unknown)

users = {u: (p, t) for u, p, t in c.execute('select user_id, platform, is_test from users')}
print('test users:', sum(1 for _, t in users.values() if t))

events = defaultdict(lambda: defaultdict(list))  # user -> name -> [ts]
for u, name, ts in c.execute('select user_id, name, ts from events'):
    events[u][name].append(ts)

funnel = defaultdict(lambda: dict.fromkeys(STEPS, 0))
for u, (platform, is_test) in users.items():
    if is_test:
        continue
    prev = None
    for step in STEPS:
        ts_list = events[u].get(step, [])
        # step counts only at or after previous step's time; first valid occurrence
        valid = [t for t in ts_list if prev is None or t >= prev]
        if not valid:
            break
        prev = min(valid)
        funnel[platform][step] += 1

result = {'funnel': {}, 'biggest_drop': {}}
for platform, counts in sorted(funnel.items()):
    result['funnel'][platform] = counts
    worst_step, worst_conv = None, None
    for i in range(1, len(STEPS)):
        prev_n, n = counts[STEPS[i-1]], counts[STEPS[i]]
        conv = n / prev_n if prev_n else 0.0
        print(platform, STEPS[i], f'{n}/{prev_n}', round(conv, 4))
        if worst_conv is None or conv < worst_conv:
            worst_conv, worst_step = conv, STEPS[i]
    result['biggest_drop'][platform] = worst_step

with open('result.json', 'w') as f:
    json.dump(result, f, indent=2)
print(json.dumps(result, indent=2))


